/// 的最长前缀，使规范回复 JSON 加末尾 LF 不超过请求的 `max_reply_bytes`；首节点即装不下则拒绝本次。
pub(super) fn closure_with(
    tx: &Transaction<'_>,
    request: &Value,
    audited: Option<&state::AuditedState>,
    table: &mut Option<ClosureTable>,
    bounds: ClosureBounds,
    stats: &mut ClosureStats,
) -> Result<Value, String> {
    exact(request, &CLOSURE_FIELDS)?;
    if request["schema_revision"] != CLOSURE_SCHEMA {
        return Err(invalid("SchemaUnsupported：财务闭包版本不符"));
    }
    let anchor = &request["anchor"];
    exact(anchor, &ANCHOR_FIELDS)?;
    let claimed = ContentRef::from_transport_json(&anchor["basis_ref"]).map_err(invalid)?;
    let path = fragment::parse_path(&request["path"]).map_err(invalid)?;
    let after = match request["after"].as_str() {
        Some("") => None,
        Some(root) => Some(sc::parse_root(root).map_err(invalid)?),
        None => return Err(invalid("after须为文本")),
    };
    let budget = positive(
        required(request, "max_reply_bytes").map_err(invalid)?,
        "max_reply_bytes",
    )
    .map_err(invalid)?;
    let budget = u64::try_from(budget).map_err(invalid)?;
    let owned;

    return Err(invalid("after 之后已无闭包节点"));
}
let mut reply = json!({"anchor":anchor,"path":request["path"],"after":request["after"],
    "target_ref":index.target.to_transport_json(),"total":digests.len().to_string(),
    "nodes":[],"next":sc::root_string(&digests[start]),"done":false,"ok":true});
// 末尾 LF 计入；占位 next 与真实值等长，done 由 false 改为 true 只会变短。
let mut used = u64::try_from(canonical_json(&reply).len()).map_err(invalid)? + 1;
let mut nodes = Vec::new();
let mut end = start;
while end < digests.len() {
    let digest = digests[end];
    let (tag, body) = match sc::NodeSource::read(&mut graph, &digest).map_err(invalid)? {
        sc::NodeRead::Found { tag, body } => (tag, body),
        sc::NodeRead::Missing => return Err(missing("已审副本缺闭包节点")),
    };
    if sc::frame(tag, &body) != digest {
        return Err(invalid("闭包节点 F(tag,body) 与摘要不符"));
    }
    let node = ProofNode {
        root: sc::root_string(&digest),
        tag: format!("{tag:02x}"),
        body_hex: hex_lower(&body),
    }
    .to_json();
    let size = u64::try_from(canonical_json(&node).len()).map_err(invalid)?
        + u64::from(!nodes.is_empty());
    if used.saturating_add(size) > budget {
        break;
    }
    used += size;
    nodes.push(node);
    end += 1;
}
if nodes.is_empty() {
    return Err(closure_refusal(
        "ClosureReplyBytes",
        "单个闭包节点超过请求的 max_reply_bytes",
    ));
}

let request = strict_json(body).map_err(invalid)?;
let s = Instant::now();
// R7(b)：anchor／会话身份不符与其他请求级拒绝一样只拒本次，会话保持有效（ANCHOR_MISMATCH_POLICY）。
let out = self.serve_audited(&command, &request, deadline, &mut t.closure)?;
let mut bytes = canonical_json(&out).into_bytes();
bytes.push(b'\n');
t.serve_us = us(s);
if bytes.len() as u64 > self.resources.max_reply_bytes {
    return Err(incomplete(
        "SessionReplyBytes",
        "回复超过会话 max_reply_bytes",
    ));

fn read_reply(stream: &mut UnixStream, deadline: Instant) -> Reply {
    let reply = read_frame(stream, CLIENT_MAX_REPLY, deadline).map_err(|f| match f {
        FrameFault::Io(e) => missing(format!("读会话回复：{e:?}")),
        FrameFault::TooLarge(_) => missing("会话回复帧超界"),
    })?;
    match reply.first() {
        Some(0) => Ok(reply[1..].to_vec()),
        Some(1) => Err(String::from_utf8_lossy(&reply[1..]).into_owned()),
        _ => Err(missing("会话回复格式错误")),
    }
}

/// 客户端：`<financial-basis-ref|financial-content|financial-closure> --protocol-revision s-session/3 --db <db>
/// --session <socket>`。只转发 stdin 原字节、自身二进制 SHA 与 --db 的 (dev, ino)，把回复原字节
/// 写到 stdout；会话拒绝即以其原因失败；从不本地审计、从不回落冷路径。
pub(super) fn client(args: &[String]) -> Result<(), String> {
    let command = args.get(1).map(String::as_str).unwrap_or_default();
    if !matches!(
        command,
        "financial-basis-ref" | "financial-content" | "financial-closure"
    ) {
        return Err(invalid("会话客户端只接受三条财务命令"));
    }
    let flags = parse_flags(
        args,
        &["--protocol-revision", "--db", "--session"],
        "会话客户端",
    )?;
    let db = Path::new(&flags.0["--db"]);
    let identity = super::financial_reader::client_db_identity(db)?;
    let mut body = Vec::new();
    std::io::stdin().read_to_end(&mut body).map_err(invalid)?;
    let sha = self_sha256()?;
    let stream = connect(&flags.0["--session"])?;
    let deadline = Instant::now() + Duration::from_millis(CLIENT_WAIT_MS);
    let reply = exchange(stream, command, &sha, identity, &body, deadline)?;
    let mut out = std::io::stdout().lock();
    out.write_all(&reply).map_err(invalid)?;

pub fn strict_json(bytes: &[u8]) -> Result<Value, String> {
    serde_json::from_slice::<Strict>(bytes)
        .map(|s| s.0)
        .map_err(|e| format!("SchemaUnsupported：{e}"))
}
